cssCode:
.trail-dot {
  position: absolute;
  width: 12px; height: 12px;
  background: #00ffcc;
  border-radius: 50%;
  box-shadow: 0 0 15px #00ffcc;
  pointer-events: none;
  animation: fadeTrail 0.8s forwards ease-out;
  transform: translate(-50%, -50%);
}
@keyframes fadeTrail {
  0% { transform: translate(-50%, -50%) scale(1); opacity: 1; }
  100% { transform: translate(-50%, -50%) scale(0.2); opacity: 0; }
}

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;position:relative;background:transparent;overflow:hidden;touch-action:none;';

const createDot = (x, y) => {
  const dot = document.createElement('div');
  dot.className = 'trail-dot';
  dot.style.left = `${x}px`;
  dot.style.top = `${y}px`;
  c.appendChild(dot);
  setTimeout(() => dot.remove(), 800);
};

c.addEventListener('pointermove', (e) => {
  const rect = c.getBoundingClientRect();
  createDot(e.clientX - rect.left, e.clientY - rect.top);
});
